import React, { useState, useEffect } from 'react';
import { Link } from 'react-router-dom';
import { useAuth } from '../../contexts/AuthContext';
import { dashboardAPI, coursesAPI, enrollmentAPI } from '../../services/api';
import { Icon, IconSizes, IconColors } from '../../components/common/IconTheme';
import './Dashboard.css';

const Dashboard = () => {
  const { user } = useAuth();
  const [stats, setStats] = useState({
    totalCourses: 0,
    enrolledCourses: 0,
    completedCourses: 0,
    totalHours: 0
  });
  const [recentCourses, setRecentCourses] = useState([]);
  const [allCourses, setAllCourses] = useState([]);
  const [enrolledCourses, setEnrolledCourses] = useState([]);
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    const fetchDashboardData = async () => {
      try {
        const [statsResponse, coursesResponse, enrolledResponse] = await Promise.all([
          dashboardAPI.getStats(),
          coursesAPI.getAll(),
          user?.role === 'apprenti' ? enrollmentAPI.getStudentCourses() : Promise.resolve({ data: { success: true, data: [] } })
        ]);

        setStats(statsResponse.data);
        setAllCourses(coursesResponse.data.data || []);
        setRecentCourses((coursesResponse.data.data || []).slice(0, 3)); // Get first 3 courses

        if (enrolledResponse.data.success) {
          // Extraire les cours depuis les enrollments
          const courses = enrolledResponse.data.data.enrollments.map(enrollment => enrollment.course);
          setEnrolledCourses(courses);
        }
      } catch (error) {
        console.error('Error fetching dashboard data:', error);
        console.error('Error details:', error.response?.data);

        // Essayer de récupérer au moins les cours même si les stats échouent
        try {
          const coursesResponse = await coursesAPI.getAll();
          if (coursesResponse.data.success) {
            setAllCourses(coursesResponse.data.data || []);
            setRecentCourses((coursesResponse.data.data || []).slice(0, 3));
          }
        } catch (coursesError) {
          console.error('Error fetching courses:', coursesError);
          setAllCourses([]);
          setRecentCourses([]);
        }

        // Utiliser des stats par défaut
        setStats({
          totalCourses: 0,
          enrolledCourses: 0,
          completedCourses: 0,
          totalHours: 0
        });
      } finally {
        setLoading(false);
      }
    };

    fetchDashboardData();
  }, [user]);

  // Fonction utilitaire pour vérifier si un cours est inscrit
  const isCourseEnrolled = (courseId) => {
    return enrolledCourses.some(course => 
      (course._id || course.id) === (courseId._id || courseId.id)
    );
  };

  if (loading) {
    return (
      <div className="main-content">
        <div className="text-center">
          <p>Chargement du tableau de bord...</p>
        </div>
      </div>
    );
  }

  return (
    <div className="main-content">
      <div className="card">
        <div className="card-header">
          <h1 className="card-title">Bon retour, {user?.name || 'Apprenti'} !</h1>
          <p style={{ color: 'var(--text-secondary)', margin: 0 }}>
            {user?.role === 'tuteur' 
              ? 'Gérez vos cours et suivez les progrès de vos apprentis'
              : 'Voici votre progression d\'apprentissage et votre activité récente'
            }
          </p>
        </div>
      </div>

      {/* Tutor Actions */}
      {user?.role === 'tuteur' && (
        <div className="card">
          <div className="card-header">
            <h2 className="card-title">Actions Tuteur</h2>
            <p style={{ color: 'var(--text-secondary)', margin: 0 }}>
              Gérez vos cours et publiez du contenu pour vos apprentis
            </p>
          </div>
          <div className="card-body">
            <div className="grid grid-2" style={{ gap: '1rem' }}>
              <Link to="/tutor/published-courses" className="btn btn-primary btn-lg" style={{ display: 'flex', alignItems: 'center', gap: '0.75rem', padding: '1rem' }}>
                <Icon name="globe" size={IconSizes.md} color={IconColors.white} />
                <div style={{ textAlign: 'left' }}>
                  <div style={{ fontWeight: '600' }}>Cours Publiés</div>
                  <div style={{ fontSize: '0.85rem', opacity: 0.9 }}>Gérer et publier vos cours</div>
                </div>
              </Link>

              <Link to="/tutor/my-courses" className="btn btn-secondary btn-lg" style={{ display: 'flex', alignItems: 'center', gap: '0.75rem', padding: '1rem' }}>
                <Icon name="courses" size={IconSizes.md} color={IconColors.white} />
                <div style={{ textAlign: 'left' }}>
                  <div style={{ fontWeight: '600' }}>Mes Cours</div>
                  <div style={{ fontSize: '0.85rem', opacity: 0.9 }}>Créer et modifier vos cours</div>
                </div>
              </Link>
            </div>
          </div>
        </div>
      )}

      {/* Student Actions */}
      {user?.role === 'apprenti' && (
        <div className="card">
          <div className="card-header">
            <h2 className="card-title">Actions Apprenti</h2>
            <p style={{ color: 'var(--text-secondary)', margin: 0 }}>
              Explorez les cours disponibles et suivez votre progression
            </p>
          </div>
          <div className="card-body">
            <div className="grid grid-2" style={{ gap: '1rem' }}>
              <Link to="/courses" className="btn btn-primary btn-lg" style={{ display: 'flex', alignItems: 'center', gap: '0.75rem', padding: '1rem' }}>
                <Icon name="courses" size={IconSizes.md} color={IconColors.white} />
                <div style={{ textAlign: 'left' }}>
                  <div style={{ fontWeight: '600' }}>Tous les Cours</div>
                  <div style={{ fontSize: '0.85rem', opacity: 0.9 }}>Découvrir les cours publiés</div>
                </div>
              </Link>

              <Link to="/certificates" className="btn btn-secondary btn-lg" style={{ display: 'flex', alignItems: 'center', gap: '0.75rem', padding: '1rem' }}>
                <Icon name="trophy" size={IconSizes.md} color={IconColors.white} />
                <div style={{ textAlign: 'left' }}>
                  <div style={{ fontWeight: '600' }}>Mes Certificats</div>
                  <div style={{ fontSize: '0.85rem', opacity: 0.9 }}>Voir mes certificats obtenus</div>
                </div>
              </Link>
            </div>
          </div>
        </div>
      )}

      {/* Stats Grid */}
      <div className="stats-grid">
        <div className="stat-card primary">
          <div className="stat-icon">
            <Icon name="courses" size={IconSizes.lg} color={IconColors.white} />
          </div>
          <div className="stat-content">
            <div className="stat-number">{allCourses.length}</div>
            <div className="stat-label">Cours disponibles</div>
            <div className="stat-description">Total sur la plateforme</div>
          </div>
        </div>
        <div className="stat-card secondary">
          <div className="stat-icon">
            <Icon name="graduation" size={IconSizes.lg} color={IconColors.white} />
          </div>
          <div className="stat-content">
            <div className="stat-number">{enrolledCourses.length}</div>
            <div className="stat-label">Cours inscrits</div>
            <div className="stat-description">Mes inscriptions</div>
          </div>
        </div>
        <div className="stat-card success">
          <div className="stat-icon">
            <Icon name="trophy" size={IconSizes.lg} color={IconColors.white} />
          </div>
          <div className="stat-content">
            <div className="stat-number">{stats.completedCourses || 0}</div>
            <div className="stat-label">Certificats obtenus</div>
            <div className="stat-description">Cours terminés avec succès</div>
          </div>
        </div>
        <div className="stat-card warning">
          <div className="stat-icon">
            <Icon name="trendingUp" size={IconSizes.lg} color={IconColors.white} />
          </div>
          <div className="stat-content">
            <div className="stat-number">
              {enrolledCourses.length > 0 && stats.completedCourses > 0 
                ? Math.round((stats.completedCourses / enrolledCourses.length) * 100)
                : 0}%
            </div>
            <div className="stat-label">Taux de réussite</div>
            <div className="stat-description">Progression moyenne</div>
          </div>
        </div>
      </div>

      {/* Tous les cours publiés - visible pour tous les utilisateurs */}
      <div className="card">
        <div className="card-header">
          <div style={{ display: 'flex', alignItems: 'center', justifyContent: 'space-between' }}>
            <div style={{ display: 'flex', alignItems: 'center', gap: '0.75rem' }}>
              <Icon name="courses" size={IconSizes.md} color={IconColors.primary} />
              <h2 className="card-title">Cours disponibles</h2>
            </div>
            <div className="courses-count">
              <span className="count-badge">{allCourses.length} cours</span>
            </div>
          </div>
          <p style={{ color: 'var(--text-secondary)', margin: 0 }}>
            {user?.role === 'apprenti' 
              ? 'Découvrez tous les cours publiés et voyez votre statut d\'inscription'
              : 'Explorez tous les cours disponibles sur la plateforme'
            }
          </p>
        </div>
        <div className="courses-grid">
          {allCourses.slice(0, 9).map((course, index) => {
            const courseIcons = ['graduation', 'rocket', 'target', 'star', 'book', 'code'];
            const iconName = courseIcons[index % courseIcons.length];
            const isEnrolled = user?.role === 'apprenti' ? isCourseEnrolled(course) : false;

            return (
              <div key={course._id || course.id} className="course-card enhanced">
                <div className="course-header">
                  <div className="course-icon">
                    <Icon name={iconName} size={IconSizes.lg} color={IconColors.white} />
                  </div>
                  <div className="course-badges">
                    <div className="course-level">
                      <Icon name="target" size={IconSizes.xs} color={IconColors.white} />
                      <span>{course.level}</span>
                    </div>
                    {isEnrolled && (
                      <div className="enrollment-badge">
                        <Icon name="check" size={IconSizes.xs} color={IconColors.white} />
                        <span>Inscrit</span>
                      </div>
                    )}
                  </div>
                </div>
                <div className="course-content">
                  <h3 className="dashboard-course-title">{course.title}</h3>
                  <p className="course-description">{course.description}</p>
                  <div className="course-meta">
                    <div className="course-duration">
                      <Icon name="clock" size={IconSizes.xs} color={IconColors.gray} />
                      <span>{course.duration}</span>
                    </div>
                    <div className="course-category">
                      <Icon name="tag" size={IconSizes.xs} color={IconColors.gray} />
                      <span>{course.category}</span>
                    </div>
                    <div className="course-students">
                      <Icon name="users" size={IconSizes.xs} color={IconColors.gray} />
                      <span>{course.enrolledStudents?.length || course.students || 0} étudiants</span>
                    </div>
                  </div>
                  <div className="course-actions">
                    <Link 
                      to={`/courses/${course._id || course.id}`} 
                      className={`btn ${isEnrolled ? 'btn-success' : 'btn-primary'} course-btn`}
                    >
                      <Icon name={isEnrolled ? "play" : "arrowRight"} size={IconSizes.xs} color={IconColors.white} />
                      {isEnrolled ? 'Continuer' : 'Voir le cours'}
                    </Link>
                  </div>
                </div>
              </div>
            );
          })}
        </div>
        <div className="text-center mt-3">
          <Link to="/courses" className="btn btn-secondary">
            <Icon name="courses" size={IconSizes.sm} color={IconColors.white} />
            Voir tous les cours
          </Link>
        </div>
      </div>


      {/* Achievements */}
      <div className="card">
        <div className="card-header">
          <div style={{ display: 'flex', alignItems: 'center', justifyContent: 'space-between' }}>
            <div style={{ display: 'flex', alignItems: 'center', gap: '0.75rem' }}>
              <Icon name="trophy" size={IconSizes.md} color={IconColors.warning} />
              <h2 className="card-title">Réalisations</h2>
            </div>
            <div className="achievements-count">
              <span className="count-badge success">{stats.completedCourses || 0} certificats</span>
            </div>
          </div>
          <p style={{ color: 'var(--text-secondary)', margin: 0 }}>
            Vos accomplissements et certificats obtenus
          </p>
        </div>
        <div className="achievements-grid">
          {[
            {
              id: 1,
              title: 'Premiers Pas',
              description: 'Terminer votre première leçon',
              icon: 'target',
              earned: enrolledCourses.length > 0,
              earnedAt: enrolledCourses.length > 0 ? new Date(Date.now() - 30 * 24 * 60 * 60 * 1000) : null
            },
            {
              id: 2,
              title: 'Champion de Cours',
              description: 'Terminer votre premier cours',
              icon: 'trophy',
              earned: (stats.completedCourses || 0) > 0,
              earnedAt: (stats.completedCourses || 0) > 0 ? new Date(Date.now() - 3 * 24 * 60 * 60 * 1000) : null
            },
            {
              id: 3,
              title: 'Maître de la Série',
              description: 'Maintenir une série d\'apprentissage de 7 jours',
              icon: 'flame',
              earned: false,
              progress: 5,
              required: 7
            },
            {
              id: 4,
              title: 'Chercheur de Connaissances',
              description: 'S\'inscrire à 5 cours',
              icon: 'graduation',
              earned: enrolledCourses.length >= 5,
              progress: Math.min(enrolledCourses.length, 5),
              required: 5
            },
            {
              id: 5,
              title: 'Collectionneur de Certificats',
              description: 'Obtenir 3 certificats',
              icon: 'award',
              earned: (stats.completedCourses || 0) >= 3,
              progress: Math.min(stats.completedCourses || 0, 3),
              required: 3
            }
          ].map((achievement) => (
            <div key={achievement.id} className={`achievement-card ${achievement.earned ? 'earned' : 'locked'}`}>
              <div className="achievement-icon">
                <Icon 
                  name={achievement.icon} 
                  size={IconSizes.lg} 
                  color={achievement.earned ? IconColors.success : IconColors.gray} 
                />
              </div>
              <div className="achievement-content">
                <h3 className="achievement-title">{achievement.title}</h3>
                <p className="achievement-description">{achievement.description}</p>
                {achievement.earned ? (
                  <span className="achievement-date">
                    Obtenu le {achievement.earnedAt?.toLocaleDateString('fr-FR') || 'Récemment'}
                  </span>
                ) : (
                  <div className="achievement-progress">
                    <div className="progress-bar">
                      <div 
                        className="progress-fill" 
                        style={{ width: `${(achievement.progress / achievement.required) * 100}%` }}
                      ></div>
                    </div>
                    <span className="progress-text">
                      {achievement.progress}/{achievement.required}
                    </span>
                  </div>
                )}
              </div>
            </div>
          ))}
        </div>
        {(stats.completedCourses || 0) > 0 && (
          <div className="text-center mt-3">
            <Link to="/certificates" className="btn btn-success">
              <Icon name="trophy" size={IconSizes.sm} color={IconColors.white} />
              Voir mes certificats ({stats.completedCourses || 0})
            </Link>
          </div>
        )}
      </div>

    </div>
  );
};

export default Dashboard;
